export type HERO_QUALITY_CATALOGRow = (typeof HERO_QUALITY_CATALOG)[number];

export function parseMotionCatalogRow(row: string): Readonly<Record<string, string>> {
  const parts = row.split("!");
  const out: Record<string, string> = Object.create(null);
  for (const part of parts) {
    const idx = part.indexOf("=");
    if (idx === -1) {
      out.id = part;
      continue;
    }
    out[part.slice(0, idx)] = part.slice(idx + 1);
  }
  return out;
}

export const HERO_QUALITY_CATALOG_COUNT = HERO_QUALITY_CATALOG.length;

